// ===================== CONFIG =====================
// LeadMailbox new lead -> GHL contact upsert (Independent Lending subaccount).
const LOCATION_ID = 'dVtkyM31aGC8IWAKrcvW';
// GHL custom-field IDs (from discovery)
const CF = {
  leadid_leadmailbox:  'ULqBh4WhEnOVUzXQjVIF', // dedicated LMB lead id (clean number)
  lead_notes:          'IjxjwllVSYwz7opJCuVp', // AI context blob
  custom_introduction: 'vadHuBnrarRKLvfcndG8', // first line the AI says
};
// ==================================================

const body = $json.body || $json || {};
const g = (k) => (body[k] != null ? String(body[k]).trim() : '');

const leadid    = g('leadid') || g('LeadID') || g('lead_id');
const firstName = g('firstname') || g('first_name') || g('First Name');
const lastName  = g('lastname')  || g('last_name')  || g('Last Name');
const email     = g('email') || g('Email');
const campaign  = g('campaign') || g('Campaign');
const phoneRaw  = g('phone') || g('Phone') || g('homephone') || g('HomePhone');

// normalize phone to +1E.164 where possible
let phone = phoneRaw.replace(/[^\d+]/g, '');
if (phone && !phone.startsWith('+')) {
  if (phone.length === 10) phone = '+1' + phone;
  else if (phone.length === 11 && phone.startsWith('1')) phone = '+' + phone;
}

// AI-context note blob (only include fields LMB actually sends)
const lines = [];
if (leadid)   lines.push('LeadMailbox Lead ID: ' + leadid);
if (campaign) lines.push('Campaign: ' + campaign);
[['property','Property'],['loan_purpose','Loan Purpose'],['loan_amount','Loan Amount'],
 ['cash_out','Cash Out'],['property_value','Property Value'],['current_loan','Current Loan'],
 ['loan_type','Loan Type'],['occupancy','Occupancy'],['credit','Credit']
].forEach(([k,label]) => { const v = g(k); if (v) lines.push(label + ': ' + v); });
const leadNotes = lines.join('\n');

// first line the AI says (hard money / Independent Lending)
const intro = "So " + (firstName || 'there') +
  ", it's just Sam from Independent Lending. You uhh submitted an inquiry about a hard money loan with us, right?";

const customFields = [];
if (leadid)   customFields.push({ id: CF.leadid_leadmailbox, value: leadid });
if (leadNotes) customFields.push({ id: CF.lead_notes, value: leadNotes });
customFields.push({ id: CF.custom_introduction, value: intro });

const contact = {
  locationId: LOCATION_ID,
  firstName: firstName || undefined,
  lastName:  lastName  || undefined,
  name: (firstName + ' ' + lastName).trim() || undefined,
  source: 'LeadMailbox',
  customFields,
};
if (phone) contact.phone = phone;
if (email && email.indexOf('@') > -1) contact.email = email; // GHL rejects empty/invalid email

return [{ json: {
  ready: !!(leadid && (phone || email)),
  reason: !leadid ? 'Missing LeadMailbox leadid.' : (!(phone || email) ? 'No phone or email to dedupe on.' : null),
  leadid,
  contact,
  raw: body,
}}];
